def rect_candidates(a,color,minarea=6,th=.6):
 h,w=a.shape; occ=(a==color).astype(int); ii=np.pad(occ.cumsum(0).cumsum(1),((1,0),(1,0)))
 out=[]
 for r0 in range(h):
  for r1 in range(r0+1,h+1):
   for c0 in range(w):
    for c1 in range(c0+1,w+1):
     area=(r1-r0)*(c1-c0)
     if area<minarea: continue
     n=ii[r1,c1]-ii[r0,c1]-ii[r1,c0]+ii[r0,c0]
     if n/area>=th: out.append((area,n,n/area,r0,r1,c0,c1))
 return sorted(out,reverse=True)
