def greedy_boxes(a,col,k=.8,threshold=5,minarea=6):
 h,w=a.shape; available=(a==col).copy(); boxes=[]
 while True:
  best=None; bestscore=threshold
  for r0 in range(h):
   for r1 in range(r0+1,h+1):
    for c0 in range(w):
     for c1 in range(c0+1,w+1):
      area=(r1-r0)*(c1-c0)
      if area<minarea:continue
      n=int(available[r0:r1,c0:c1].sum())
      score=n-k*(area-n)
      if score>bestscore:
       bestscore=score;best=(r0,r1,c0,c1,n,area)
  if best is None: break
  r0,r1,c0,c1,n,area=best; boxes.append((best,round(bestscore,2)))
  available[r0:r1,c0:c1]=False
 return boxes
