def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = [sum(row.count(c) for row in grid) for c in range(10)]
    bg = max(range(10), key=lambda c: counts[c])
    output = [[bg for _ in range(w)] for _ in range(h)]
    for color in range(10):
        if color == bg:
            continue
        available = [[grid[r][c] == color for c in range(w)] for r in range(h)]
        while True:
            # Prefix sums make each rectangle's color count constant time.
            pref = [[0] * (w + 1) for _ in range(h + 1)]
            for r in range(h):
                row_sum = 0
                for c in range(w):
                    row_sum += available[r][c]
                    pref[r + 1][c + 1] = pref[r][c + 1] + row_sum
            best = None
            best_score = 2.3
            for r0 in range(h):
                for r1 in range(r0 + 1, h + 1):
                    for c0 in range(w):
                        for c1 in range(c0 + 1, w + 1):
                            area = (r1 - r0) * (c1 - c0)
                            if area < 6:
                                continue
                            n = pref[r1][c1] - pref[r0][c1] - pref[r1][c0] + pref[r0][c0]
                            score = n - 0.8 * (area - n)
                            if score > best_score:
                                best_score = score
                                best = (r0, r1, c0, c1)
            if best is None:
                break
            r0, r1, c0, c1 = best
            for r in range(r0, r1):
                for c in range(c0, c1):
                    output[r][c] = color
                    available[r][c] = False
    return output

